  `real_value_euros` decimal(18,2) DEFAULT 0.00,
  `booked` decimal(18,2) DEFAULT 0.00,
  `booked_euros` decimal(18,2) DEFAULT 0.00,
  `percentage` decimal(10,2) DEFAULT 0.00,
  `executed_dollars` decimal(18,2) DEFAULT 0.00,
