) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Transform the legacy dump to the current Laravel data schema.
-- Only rows linked to an existing project are imported.

  `id`, `project_id`, `area`, `group_1`, `group_2`, `description`,
  `general_classification`, `item_type`, `unit`, `qty`, `unit_price`,
  `global_price`, `stage`, `real_value`, `committed`, `percentage`,
  `executed_dollars`, `executed_euros`, `supplier`, `code`, `order_no`,
  `input_num`, `observations`, `booked`, `global_price_euros`,
  `real_value_euros`, `booked_euros`, `created_at`, `updated_at`
)
SELECT
  legacy.`id`,
  legacy.`project_id`,
  legacy.`area`,
  legacy.`group_1`,
  legacy.`group_2`,
  legacy.`description`,
  legacy.`general_classification`,
  legacy.`item_type`,
  legacy.`unit`,
  COALESCE(legacy.`qty`, 0),
  COALESCE(legacy.`unit_price`, 0),
  COALESCE(legacy.`global_price`, 0),
  legacy.`stage`,
  COALESCE(legacy.`real_value`, 0),
  0 AS `committed`,
  COALESCE(legacy.`percentage`, 0),
  COALESCE(legacy.`executed_dollars`, 0),
  COALESCE(legacy.`executed_euros`, 0),
  legacy.`supplier`,
  legacy.`code`,
  legacy.`order_no`,
  legacy.`input_num`,
  legacy.`observations`,
  COALESCE(legacy.`booked`, 0),
  COALESCE(legacy.`global_price_euros`, 0),
  COALESCE(legacy.`real_value_euros`, 0),
  COALESCE(legacy.`booked_euros`, 0),
  legacy.`created_at`,
  legacy.`updated_at`
FROM `legacy_data` AS legacy
INNER JOIN `projects`
  ON `projects`.`id` = legacy.`project_id`;

UPDATE `projects`
SET `data_uploaded` = EXISTS (
  SELECT 1
  FROM `data`
  WHERE `data`.`project_id` = `projects`.`id`
);

DROP TABLE `legacy_data`;

SET foreign_key_checks = 1;

